window.AUTH=window.AUTH||{};window.AUTH["17-1077"]={"d":"17-1077","id":"2018/17-1077","n":"Lorenzo v. Securities and Exchange Commission","briefs":[{"k":"petitioner","label":"Brief of petitioner Francis V. Lorenzo","date":"2018-08-20","url":"https://www.supremecourt.gov/DocketPDF/17/17-1077/60038/20180820140401235_17-1077%20ts--PDFA.pdf","side":"pet","n":48},{"k":"respondent","label":"Brief of respondent Securities and Exchange Commission","date":"2018-10-05","url":"https://www.supremecourt.gov/DocketPDF/17/17-1077/66089/20181005171520730_17-1077bsUnitedStates.pdf","side":"res","n":61},{"k":"reply","label":"Reply of petitioner Francis V. Lorenzo","date":"2018-11-01","url":"https://www.supremecourt.gov/DocketPDF/17/17-1077/70732/20181101134745347_17-1077%20Reply%20Brief.pdf","side":"pet","n":33}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1077_21o3.pdf","tr":true,"items":[{"t":"case","label":"Aaron v. SEC","cite":"446 U.S. 680","y":1980,"id":"1979/79-66","sc":1,"by":{"0":"57, 58","1":"16"},"q":[{"src":"brief","b":0,"text":"will not justify reading a provision more broadly than its language and the statutory scheme reasonably permit.","cite":"446 U.S. 680, 695"},{"src":"brief","b":1,"text":"[t]hat which is devised, or formed by design.","cite":"446 U.S. 680, 696 n.13"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"‘a mental state embracing intent to deceive, manipulate, or defraud.’","cite":"446 U. S. 680, 686"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"the terms ‘device,’ ‘scheme,’ and ‘artifice’ all connote knowing or intentional practices.","cite":"446 U. S. 680, 696"}]},{"t":"case","label":"Amgen Inc. v. Connecticut Retirement Plans and Trust Funds","cite":"568 U.S. 455","y":2013,"id":"2012/11-1085","sc":1,"by":{"0":"5","1":"39"},"q":[{"src":"brief","b":1,"text":"Congress later fortified the PSLRA by enacting the Securities Litigation Uniform Standards Act of 1998, 112 Stat. 3227, which curtailed plaintiffs’ ability to evade the PSLRA’s limitations on federal securities-fraud litigation by bringing class-action suits under state rather than federal law.","cite":"568 U.S. 455, 476"}]},{"t":"case","label":"Anixter v. Home-Stake Prod. Co.","cite":"77 F.3d 1215","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/77/1215/","by":{"0":"38"}},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"by":{"0":"21, 43, 57"}},{"t":"case","label":"Central Bank of Denver, NIA. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"by":{"0":"passim","1":"passim","2":"passim"},"q":[{"src":"brief","b":0,"text":"giving aid to a person who commits a manipulative or deceptive act","cite":"511 U.S. at 177"},{"src":"brief","b":0,"text":"the scope of conduct prohibited by § 10(b), the text of the statute controls.","cite":"511 U.S. at 173, 177"},{"src":"brief","b":1,"text":"[S]tatutory text controls the definition of conduct covered by","cite":"511 U.S. 164, 175"},{"src":"brief","b":2,"text":"prohibits only the making of a material misstatement (or omission) or the commission of a manipulative act. . . . We cannot amend the statute to create liability for acts that are not themselves manipulative or deceptive within the meaning of the statute.","cite":"511 U.S. at 177"},{"src":"argument","who":"Justice Kagan","text":"Heim, we've made very clear in Central Bank that this idea of primary and secondary, if your actions fit within the language of the particular provision of the statute that you're charged on, then you're a primary violator of that provision."},{"src":"argument","who":"Justice Kagan","text":"But what we said in Central Bank is, look, if you do the thing that's -- that is described in a particular subsection of this statute or of the -- or of 10b-5, the rule that implements it, then you're a primary violator as to that subsection."},{"src":"argument","who":"Mr. Heim","text":"And, you know, an additional related point to that is that this Court's holdings in Central Bank, Santa Fe, and other cases confine Rule 10b-5(b) to the boundaries of Section 10(b)."}]},{"t":"case","label":"Charal Inv. Co. v. Rockefeller","cite":"131 F. Supp. 2d 593","y":2001,"court":"D. Del.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/131/593/","by":{"0":"52, 53"}},{"t":"case","label":"Chiarella v. United States","cite":"445 U.S. 222","y":1980,"id":"1979/78-1202","sc":1,"by":{"0":"51","1":"4, 21, 29","2":"8, 10, 13"},"q":[{"src":"brief","b":1,"text":"was designed as a 1 Unless otherwise indicated, all citations to the United States Code refer to the 2006 version, which was the law in force at the time of petitioner’s conduct. Subsequent amendments are immaterial to the issues in this case. catch-all clause to prevent fraudulent practices.","cite":"445 U.S. 222, 226"},{"src":"argument","who":"Mr. Heim","text":"And the Chiarella case stands for the proposition that, unless there's a misstatement or an omission or some sort of manipulative trading, that those are essentially the three categories of fraud that are proscribed by Section 10(b)."}]},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"by":{"0":"29","2":"5"},"q":[{"src":"brief","b":2,"text":"text in a way that makes part of it redundant.","cite":"556 U.S. 303, 314"},{"src":"argument","who":"Mr. Heim","text":"And that would be contrary to the - to the holding of Corley versus United States, where the Court is -- is -- the purpose is to find meaning for each of the different subsections and not read it in a way that would make one of them redundant."}]},{"t":"case","label":"Damato v. Hermanson","cite":"153 F.3d 464","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/153/464/","by":{"0":"52"}},{"t":"case","label":"Desai v. Deutsche Bank Sec., Ltd.","cite":"573 F.3d 931","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/573/931/","by":{"0":"6, 29, 31, 32"},"q":[{"src":"argument","who":"Mr. Heim","text":"But, as Desai said, in the circuit court of appeals, is that the judiciary's always recognized a difference between deceptive conduct and deceptive statements."}]},{"t":"case","label":"Dirks v. SEC","cite":"463 U.S. 646","y":1983,"id":"1982/82-276","sc":1,"by":{"0":"43"}},{"t":"case","label":"Dolphin & Bradbury, Inc. v. SEC","cite":"512 F.3d 634","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/512/634/","by":{"0":"13"}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"by":{"0":"passim","1":"15, 22","2":"11, 13"},"q":[{"src":"brief","b":0,"text":"‘[T]he starting point in every case involving construction of a statute is the language itself.’","cite":"425 U.S. 185, 197"},{"src":"brief","b":0,"text":"‘refers generally to practices, such as wash sales, matched orders, or rigged prices, that are intended to mislead investors by artificially affecting market activity","cite":"425 U.S. 185, 199"},{"src":"brief","b":1,"text":"gloss to the operative language of the statute quite different from its commonly accepted meaning,","cite":"425 U.S. at 199"}]},{"t":"case","label":"Flannery v. SEC","cite":"810 F.3d 1","y":2012,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/810/1/","by":{"0":"8"}},{"t":"case","label":"Foss v. Bear, Stearns & Co.","cite":"394 F.3d 540","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/394/540/","by":{"0":"53"},"q":[{"src":"brief","b":0,"text":"Foss wants us to call the conduct ‘manipulation’ rather than ‘fraud,’ but this is a distinction without a difference. In securities law, manipulation is a kind of fraud; deceit remains essential.","cite":"394 F.3d 540, 542"}]},{"t":"case","label":"Green v. Santa Fe Industries, Inc.","cite":"533 F.2d 1283","y":1976,"court":"2nd Cir.","url":"https://www.courtlistener.com/c/F.2d/533/1283/","by":{"0":"51"}},{"t":"case","label":"Hibbs v. Winn","cite":"542 U.S. 88","y":2004,"id":"2003/02-1809","sc":1,"by":{"0":"29"}},{"t":"case","label":"Janus Capital Group, Inc. v. First Derivative Traders","cite":"564 U.S. 135","y":2011,"id":"2010/09-525","sc":1,"by":{"0":"passim","1":"10, 12, 22, 23, 24","2":"passim"},"q":[{"src":"brief","b":0,"text":"A broader reading of ‘make,’ including persons or entities without ultimate control over the content of a statement, would substantially undermine Central Bank. If persons or entities without control over the content of a statement could be considered primary violators who ‘made’ the statement, then aiders and abettors would be almost nonexistent.","cite":"564 U.S. at 143"},{"src":"argument","who":"Mr. Heim","text":"Chief Justice, and may it please the Court: In Janus Capital, this Court held that only the maker of a misstatement can be held liable for that misstatement under Section 10(b) and Rule 10b-5(b)."},{"src":"argument","who":"Justice Sotomayor","text":"Excuse me, Janus was a private cause of action, correct?"},{"src":"argument","who":"Justice Sotomayor","text":"I -- I understand what Janus said, but I don't know how it squares with 17(a). And you swept 17(a) in. 10b-5 uses the phrase \"to make\" any untrue statement."}]},{"t":"case","label":"Landry v. All Am. Assurance Co.","cite":"688 F.2d 381","y":1982,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/688/381/","by":{"0":"5, 23"}},{"t":"case","label":"Lentell v. Merrill Lynch & Co.","cite":"396 F.3d 161","y":2005,"url":"https://www.courtlistener.com/c/F.3d/396/161/","by":{"0":"30, 31, 53"}},{"t":"case","label":"Pinter v. Dahl","cite":"486 U.S. 622","y":1988,"id":"1987/86-805","sc":1,"by":{"0":"58","2":"21"}},{"t":"case","label":"Public Pension Fund Group v. KV Pharmaceutical Co.","cite":"679 F.3d 972","y":2012,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/679/972/","by":{"0":"33"}},{"t":"case","label":"Regents of Univ. of Cal. v. Credit Suisse First Boston (USA), Inc.","cite":"482 F.3d 372","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/482/372/","by":{"0":"37, 58"},"q":[{"src":"brief","b":0,"text":"[i]n Central Bank, the Court emphasized that securities fraud liability is an area of the law that demands certainty and predictability. Secondary liability brings neither; instead it gives rise to confusion about the extent of secondary actors’ obligations and invites vague and conflicting standards of proof in divers courts.","cite":"482 F.3d 372, 386"}]},{"t":"case","label":"Santa Fe Indus., Inc. v. Green","cite":"430 U.S. 462","y":1977,"id":"1976/75-1753","sc":1,"by":{"0":"passim","1":"21","2":"10"},"q":[{"src":"brief","b":0,"text":"The language of § 10(b) gives no indication that Congress meant to prohibit any conduct not involving manipulation or deception.","cite":"430 U.S. 462, 473"},{"src":"brief","b":0,"text":"breaches of fiduciary duty by a majority against minority shareholders without any charge of misrepresentation or lack of disclosure","cite":"430 U.S. at 470"},{"src":"brief","b":2,"text":"[t]he language of §10(b) gives no indication that Congress meant to prohibit any conduct not involving manipulation or deception.","cite":"430 U.S. 462, 473"}]},{"t":"case","label":"Schreiber v. Burlington N., Inc.","cite":"472 U.S. 1","y":1985,"id":"1984/83-2129","sc":1,"by":{"0":"54"}},{"t":"case","label":"SEC v. Apuzzo","cite":"689 F.3d 204","y":2012,"court":"2nd Cir.","url":"https://www.courtlistener.com/c/F.3d/689/204/","by":{"0":"45"},"q":[{"src":"brief","b":0,"text":"(1) the existence of a securities law violation by the primary (as opposed to the aiding and abetting) party; (2) ‘knowledge’ of this violation on the part of the aider and abettor; and (3) ‘substantial assistance’ by the aider and abettor in the achievement of the primary violation.","cite":"689 F.3d 204, 206"}]},{"t":"case","label":"SEC v. Big Apple Consulting USA, Inc.","cite":"783 F.3d 786","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/783/786/","by":{"0":"33, 34","1":"25"}},{"t":"case","label":"SEC v. First Jersey Sec., Inc.","cite":"101 F.3d 1450","y":1996,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/101/1450/","by":{"0":"5, 23"}},{"t":"case","label":"SEC v. KPMG LLP","cite":"412 F. Supp. 2d 349","y":2006,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/412/349/","by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"Because the core misconduct alleged is in fact a misstatement, it would be improper to impose primary liability . . . by designating the alleged fraud a manipulative device rather than a misstatement.","cite":"412 F. Supp. 2d 349, 378"}]},{"t":"case","label":"SEC v. Kelly","cite":"817 F. Supp. 2d 340","y":2011,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/817/340/","by":{"0":"passim"},"q":[{"src":"brief","b":0,"text":"to attach to individuals who did no more than facilitate preparation of material misrepresentations or omissions actually communicated by others ... would swallow the brightline test between primary and secondary liability.","cite":"817 F. Supp. 2d 340, 343-44"},{"src":"brief","b":0,"text":"Where the primary purpose and effect of a purported scheme is to make a public misrepresentation or omission, courts have routinely rejected the SEC’s attempt to bypass the elements necessary to impose ‘misstatement’ liability under subsection (b) by labeling the alleged misconduct a ‘scheme’ rather than a ‘misstatement.’","cite":"817 F. Supp. 2d at 344"}]},{"t":"case","label":"SEC v. Monarch Funding Corp.","cite":"192 F.3d 295","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/192/295/","by":{"0":"5, 23"}},{"t":"case","label":"SEC v. Monterosso","cite":"756 F.3d 1326","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1326/","by":{"0":"33, 34","1":"25"},"q":[{"src":"brief","b":0,"text":"[S]ubsection (b) was the only subsection at issue in Janus","cite":"756 F.3d 1326, 1334"}]},{"t":"case","label":"SEC v. Morgan Keegan & Co.","cite":"678 F.3d 1233","y":2012,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/678/1233/","by":{"0":"24","1":"34, 38"}},{"t":"case","label":"SEC v. Pentagon Capital Mgmt. PLC","cite":"725 F.3d 279","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/725/279/","by":{"0":"23, 24","1":"25"}},{"t":"case","label":"SEC v. PIMCO Advisors Fund Management LLC","cite":"341 F. Supp. 2d 454","y":2004,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/341/454/","by":{"0":"7, 30, 48"},"q":[{"src":"brief","b":0,"text":"to attach to individuals who did no more than facilitate preparation of material misrepresentations or omissions actually communicated by others ... would swallow the brightline test between primary and secondary liability.","cite":"341 F. Supp. 2d 454, 467"}]},{"t":"case","label":"SEC v. Sloan","cite":"436 U.S. 103","y":1978,"id":"1977/76-1607","sc":1,"by":{"0":"58"}},{"t":"case","label":"SEC v. Washington Cnty. Util. Dist.","cite":"676 F.2d 218","y":1982,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/676/218/","by":{"0":"24"}},{"t":"case","label":"Stoneridge Investment Partners, LLC v. ScientificAtlanta, Inc.","cite":"552 U.S. 148","y":2008,"id":"2007/06-43","sc":1,"by":{"0":"passim","1":"passim","2":"6, 7, 21, 22"},"q":[{"src":"brief","b":1,"text":"each of the elements or preconditions for liability","cite":"552 U.S. at 158"},{"src":"brief","b":2,"text":"Section 10(b) does not incorporate common-law fraud into federal law.","cite":"552 U.S. at 162"},{"src":"brief","b":2,"text":"extensive discovery and the potential for uncertainty and disruption in a lawsuit.","cite":"552 U.S. at 163"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"encompasses only conduct already prohibited by §10(b).","cite":"552 U. S. 148, 157"},{"src":"argument","who":"Mr. Michel","text":"To start with, the Stoneridge opinion expressly says that the petitioner's course of conduct included both oral and written statements. So this Court has made clear that conduct can include statements."}]},{"t":"case","label":"Touche Ross & Co. v. Redington","cite":"442 U.S. 560","y":1979,"id":"1978/78-309","sc":1,"by":{"0":"58"}},{"t":"case","label":"WPP Luxembourg Gamma Three Sarl v. Spot Runner, Inc.","cite":"655 F.3d 1039","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/655/1039/","by":{"0":"32, 33"}},{"t":"usc","label":"15 U.S.C. § 77q","url":"https://www.law.cornell.edu/uscode/text/15/77q","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(b)"],"stext":{"head":"§77q. Fraudulent interstate transactions","paras":[[0,"(a) Use of interstate commerce for purpose of fraud or deceit"],[0,"It shall be unlawful for any person in the offer or sale of any securities (including security-based swaps) or any security-based swap agreement (as defined in section 78c(a)(78) 1 of this title) by the use of any means or instruments of transportation or communication in interstate commerce or by use of the mails, directly or indirectly—"],[1,"(1) to employ any device, scheme, or artifice to defraud, or"],[1,"(2) to obtain money or property by means of any untrue statement of a material fact or any omission to state a material fact necessary in order to make the statements made, in light of the circumstances under which they were made, not misleading; or"],[1,"(3) to engage in any transaction, practice, or course of business which operates or would operate as a fraud or deceit upon the purchaser."],[0,"(b) Use of interstate commerce for purpose of offering for sale"],[0,"It shall be unlawful for any person, by the use of any means or instruments of transportation or communication in interstate commerce or by the use of the mails, to publish, give publicity to, or circulate any notice, circular, advertisement, newspaper, article, letter, investment service, or communication which, though not purporting to offer a security for sale, describes such security for a consideration received or to be received, directly or indirectly, from an issuer, underwriter, or dealer, without fully disclosing the receipt, whether past or prospective, of such consideration and the amount thereof."],[0,"(c) Exemptions of section 77c not applicable to this section"],[0,"The exemptions provided in section 77c of this title shall not apply to the provisions of this section."],[0,"(d) Authority with respect to security-based swap agreements"],[0,"The authority of the Commission under this section with respect to security-based swap agreements (as defined in section 78c(a)(78) of this title) shall be subject to the restrictions and limitations of section 77b–1(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77q?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"2, 2, 2, 2","2":"passim, 12"},"q":[{"src":"brief","b":1,"text":"act, practice, or course of business which operates as a fraud.","cite":"15 U.S.C. 77q(a)(1)"},{"src":"brief","b":1,"text":"to employ any device, scheme, or artifice to defraud","cite":"15 U.S.C. 77q(a)(1)"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securitiesbased swap agreement[,] any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as Appendix to opinion of the Court necessary or appropriate in the public interest or for the protection of investors.","cite":"15 U. S. C. §77q"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"(3) to engage in any transaction, practice, or course of business which operates or would operate as a fraud or deceit upon the purchaser.","cite":"15 U. S. C. §77q(a)(1)"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"obtain[s] money or property by means of","cite":"15 U. S. C. §77q(a)(2)"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"engag[ing] in any act, practice, or course of business","cite":"15 U. S. C. §77q(a)(1)"}]},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"stext":{"head":"§78j. Manipulative and deceptive devices","paras":[[0,"It shall be unlawful for any person, directly or indirectly, by the use of any means or instrumentality of interstate commerce or of the mails, or of any facility of any national securities exchange—"],[1,"(a)(1) To effect a short sale, or to use or employ any stop-loss order in connection with the purchase or sale, of any security other than a government security, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Paragraph (1) of this subsection shall not apply to security futures products."],[1,"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securities-based swap agreement 1 any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(c)(1) To effect, accept, or facilitate a transaction involving the loan or borrowing of securities in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Nothing in paragraph (1) may be construed to limit the authority of the appropriate Federal banking agency (as defined in section 1813(q) of title 12), the National Credit Union Administration, or any other Federal department or agency having a responsibility under Federal law to prescribe rules or regulations restricting transactions involving the loan or borrowing of securities in order to protect the safety and soundness of a financial institution or to protect the financial system from systemic risk."],[0,"Rules promulgated under subsection (b) that prohibit fraud, manipulation, or insider trading (but not rules imposing or specifying reporting or recordkeeping requirements, procedures, or standards as prophylactic measures against fraud, manipulation, or insider trading), and judicial precedents decided under subsection (b) and rules promulgated thereunder that prohibit fraud, manipulation, or insider trading, shall apply to security-based swap agreements to the same extent as they apply to securities. Judicial precedents decided under section 77q(a) of this title and sections 78i, 78o, 78p, 78t, and 78u–1 of this title, and judicial precedents decided under applicable rules promulgated under such sections, shall apply to security-based swap agreements to the same extent as they apply to securities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78j?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"32, 39","2":"passim"},"q":[{"src":"brief","b":1,"text":"unlawful for any person * * * [t]o use or employ, in connection with the purchase or sale of any security * * * , any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the [Securities and Exchange] Commission may prescribe.","cite":"15 U.S.C. 78j(b)"},{"src":"brief","b":1,"text":"use or employ, in connection with the purchase or sale of any security * * * any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe.","cite":"15 U.S.C. 78j(b)"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"(c) To engage in any act, practice, or course of business which operates or would operate as a fraud or deceit upon any person in connection with the purchase or sale of any security.","cite":"15 U. S. C. §78j"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"[t]o use or employ . . . any manipulative or deceptive device or contrivance","cite":"15 U. S. C. §78j(b)"}]},{"t":"usc","label":"15 U.S.C. § 78o","url":"https://www.law.cornell.edu/uscode/text/15/78o","subs":["(b)(4)(E)","(b)(6)(A)"],"stext":{"head":"§78o. Registration and regulation of brokers and dealers","paras":[[0,"(a) Registration of all persons utilizing exchange facilities to effect transactions; exemptions"],[0,"(1) It shall be unlawful for any broker or dealer which is either a person other than a natural person or a natural person not associated with a broker or dealer which is a person other than a natural person (other than such a broker or dealer whose business is exclusively intrastate and who does not make use of any facility of a national securities exchange) to make use of the mails or any means or instrumentality of interstate commerce to effect any transactions in, or to induce or attempt to induce the purchase or sale of, any security (other than an exempted security or commercial paper, bankers' acceptances, or commercial bills) unless such broker or dealer is registered in accordance with subsection (b) of this section."],[0,"(2) The Commission, by rule or order, as it deems consistent with the public interest and the protection of investors, may conditionally or unconditionally exempt from paragraph (1) of this subsection any broker or dealer or class of brokers or dealers specified in such rule or order."],[0,"(b) Manner of registration of brokers and dealers"],[0,"(1) A broker or dealer may be registered by filing with the Commission an application for registration in such form and containing such information and documents concerning such broker or dealer and any persons associated with such broker or dealer as the Commission, by rule, may prescribe as necessary or appropriate in the public interest or for the protection of investors. Within forty-five days of the date of the filing of such application (or within such longer period as to which the applicant consents), the Commission shall—"],[1,"(A) by order grant registration, or"],[1,"(B) institute proceedings to determine whether registration should be denied. Such proceedings shall include notice of the grounds for denial under consideration and opportunity for hearing and shall be concluded within one hundred twenty days of the date of the filing of the application for registration. At the conclusion of such proceedings, the Commission, by order, shall grant or deny such registration. The Commission may extend the time for conclusion of such proceedings for up to ninety days if it finds good cause for such extension and publishes its reasons for so finding or for such longer period as to which the applicant consents."],[0,"The Commission shall grant such registration if the Commission finds that the requirements of this section are satisfied. The order granting registration shall not be effective until such broker or dealer has become a member of a registered securities association, or until such broker or dealer has become a member of a national securities exchange, if such broker or dealer effects transactions solely on that exchange, unless the Commission has exempted such broker or dealer, by rule or order, from such membership. The Commission shall deny such registration if it does not make such a finding or if it finds that if the applicant were so registered, its registration would be subject to suspension or revocation under paragraph (4) of this subsection."],[0,"(2)(A) An application for registration of a broker or dealer to be formed or organized may be made by a broker or dealer to which the broker or dealer to be formed or organized is to be the successor. Such application, in such form as the Commission, by rule, may prescribe, shall contain such information and documents concerning the applicant, the successor, and any persons associated with the applicant or the successor, as the Commission, by rule, may prescribe as necessary or appropriate in the public interest or for the protection of investors. The grant or denial of registration to such an applicant shall be in accordance with the procedures set forth in paragraph (1) of this subsection. If the Commission grants such registration, the registration shall terminate on the forty-fifth day after the effective date thereof, unless prior thereto the successor shall, in accordance with such rules and regulations as the Commission may prescribe, adopt the application for registration as its own."],[0,"(B) Any person who is a broker or dealer solely by reason of acting as a municipal securities dealer or municipal securities broker, who so acts through a separately identifiable department or division, and who so acted in such a manner on June 4, 1975, may, in accordance with such terms and conditions as the Commission, by rule, prescribes as necessary and appropriate in the public interest and for the protection of investors, register such separately identifiable department or division in accordance with this subsection. If any such department or division is so registered, the department or division and not such person himself shall be the broker or dealer for purposes of this chapter."],[0,"(C) Within six months of the date of the granting of registration to a broker or dealer, the Commission, or upon the authorization and direction of the Commission, a registered securities association or national securities exchange of which such broker or dealer is a member, shall conduct an inspection of the broker or dealer to determine whether it is operating in conformity with the provisions of this chapter and the rules and regulations thereunder: Provided, however, That the Commission may delay such inspection of any class of brokers or dealers for a period not to exceed six months."],[0,"(3) Any provision of this chapter (other than section 78e of this title and subsection (a) of this section) which prohibits any act, practice, or course of business if the mails or any means or instrumentality of interstate commerce is used in connection therewith shall also prohibit any such act, practice, or course of business by any registered broker or dealer or any person acting on behalf of such a broker or dealer, irrespective of any use of the mails or any means or instrumentality of interstate commerce in connection therewith."],[0,"(4) The Commission, by order, shall censure, place limitations on the activities, functions, or operations of, suspend for a period not exceeding twelve months, or revoke the registration of any broker or dealer if it finds, on the record after notice and opportunity for hearing, that such censure, placing of limitations, suspension, or revocation is in the public interest and that such broker or dealer, whether prior or subsequent to becoming such, or any person associated with such broker or dealer, whether prior or subsequent to becoming so associated—"],[1,"(A) has willfully made or caused to be made in any application for registration or report required to be filed with the Commission or with any other appropriate regulatory agency under this chapter, or in any proceeding before the Commission with respect to registration, any statement which was at the time and in the light of the circumstances under which it was made false or misleading with respect to any material fact, or has omitted to state in any such application or report any material fact which is required to be stated therein."],[1,"(B) has been convicted within ten years preceding the filing of any application for registration or at any time thereafter of any felony or misdemeanor or of a substantially equivalent crime by a foreign court of competent jurisdiction which the Commission finds—"],[2,"(i) involves the purchase or sale of any security, the taking of a false oath, the making of a false report, bribery, perjury, burglary, any substantially equivalent activity however denominated by the laws of the relevant foreign government, or conspiracy to commit any such offense;"],[2,"(ii) arises out of the conduct of the business of a broker, dealer, municipal securities dealer municipal advisor,,1 government securities broker, government securities dealer, investment adviser, bank, insurance company, fiduciary, transfer agent, nationally recognized statistical rating organization, foreign person performing a function substantially equivalent to any of the above, or entity or person required to be registered under the Commodity Exchange Act (7 U.S.C. 1 et seq.) or any substantially equivalent foreign statute or regulation;"],[2,"(iii) involves the larceny, theft, robbery, extortion, forgery, counterfeiting, fraudulent concealment, embezzlement, fraudulent conversion, or misappropriation of funds, or securities, or substantially equivalent activity however denominated by the laws of the relevant foreign government; or"],[2,"(iv) involves the violation of section 152, 1341, 1342, or 1343 or chapter 25 or 47 of title 18 or a violation of a substantially equivalent foreign statute."],[1,"(C) is permanently or temporarily enjoined by order, judgment, or decree of any court of competent jurisdiction from acting as an investment adviser, underwriter, broker, dealer, municipal securities dealer municipal advisor,,1 government securities broker, government securities dealer, security-based swap dealer, major security-based swap participant, transfer agent, nationally recognized statistical rating organization, foreign person performing a function substantially equivalent to any of the above, or entity or person required to be registered under the Commodity Exchange Act or any substantially equivalent foreign statute or regulation, or as an affiliated person or employee of any investment company, bank, insurance company, foreign entity substantially equivalent to any of the above, or entity or person required to be registered under the Commodity Exchange Act or any substantially equivalent foreign statute or regulation, or from engaging in or continuing any conduct or practice in connection with any such activity, or in connection with the purchase or sale of any security."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78o?type=usc&year=mostrecent&link-type=html"},"by":{"0":"21, 56, 21, 56"},"q":[{"src":"brief","b":0,"text":"willfully aided, abetted, counseled, commanded, induced, or procured","cite":"15 U.S.C. §§ 78o(b)(4)(E)"}]},{"t":"usc","label":"15 U.S.C. § 78t","url":"https://www.law.cornell.edu/uscode/text/15/78t","subs":["(e)"],"stext":{"head":"§78t. Liability of controlling persons and persons who aid and abet violations","paras":[[0,"(a) Joint and several liability; good faith defense"],[0,"Every person who, directly or indirectly, controls any person liable under any provision of this chapter or of any rule or regulation thereunder shall also be liable jointly and severally with and to the same extent as such controlled person to any person to whom such controlled person is liable (including to the Commission in any action brought under paragraph (1) or (3) of section 78u(d) of this title), unless the controlling person acted in good faith and did not directly or indirectly induce the act or acts constituting the violation or cause of action."],[0,"(b) Unlawful activity through or by means of any other person"],[0,"It shall be unlawful for any person, directly or indirectly, to do any act or thing which it would be unlawful for such person to do under the provisions of this chapter or any rule or regulation thereunder through or by means of any other person."],[0,"(c) Hindering, delaying, or obstructing the making or filing of any document, report, or information"],[0,"It shall be unlawful for any director or officer of, or any owner of any securities issued by, any issuer required to file any document, report, or information under this chapter or any rule or regulation thereunder without just cause to hinder, delay, or obstruct the making or filing of any such document, report, or information."],[0,"(d) Liability for trading in securities while in possession of material nonpublic information"],[0,"Wherever communicating, or purchasing or selling a security while in possession of, material nonpublic information would violate, or result in liability to any purchaser or seller of the security under any provisions of this chapter, or any rule or regulation thereunder, such conduct in connection with a purchase or sale of a put, call, straddle, option, privilege or security-based swap agreement with respect to such security or with respect to a group or index of securities including such security, shall also violate and result in comparable liability to any purchaser or seller of that security under such provision, rule, or regulation."],[0,"(e) Prosecution of persons who aid and abet violations"],[0,"For purposes of any action brought by the Commission under paragraph (1) or (3) of section 78u(d) of this title, any person that knowingly or recklessly provides substantial assistance to another person in violation of a provision of this chapter, or of any rule or regulation issued under this chapter, shall be deemed to be in violation of such provision to the same extent as the person to whom such assistance is provided."],[0,"(f) Limitation on Commission authority"],[0,"The authority of the Commission under this section with respect to security-based swap agreements shall be subject to the restrictions and limitations of section 78c–1(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78t?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"32, 39","2":"20, 22"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"(3) to engage in any transaction, practice, or course of business which operates or would operate as a fraud or deceit upon the purchaser.","cite":"15 U. S. C. §78t"}]},{"t":"usc","label":"15 U.S.C. § 78u-2","url":"https://www.law.cornell.edu/uscode/text/15/78u-2","subs":["(a)(2)"],"by":{"0":"21, 56"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"law","label":"Private Securities Litigation Reform Act, Pub. L. No. 104-69","url":"https://www.govinfo.gov/link/plaw/104/public/69","by":{"0":"20, 38, 40"}},{"t":"case","label":"Affiliated Ute Citizens v. United States","cite":"406 U.S. 128","y":1972,"id":"1971/70-78","sc":1,"by":{"1":"18, 26, 29, 30"},"q":[{"src":"argument","who":"Mr. Michel","text":"In fact, you know, this Court has repeatedly rejected that kind of field preemption or exclusive remedy argument in the securities laws, most prominently in the Affiliated Ute case, where the Court says quite literally even though petitioner is not -- or the securities seller in that case is not liable under (b), he is liable under (a) and (c) because those provisions are not so restricted."},{"src":"argument","who":"Mr. Michel","text":"And as I said earlier, the Affiliated Ute case, I think, is -- is squarely on point and says somebody can be liable under (a) and (c) even if they're not liable under (b)."}]},{"t":"case","label":"Bank of Commerce & Trust Co. v. Schooner","cite":"160 N.E. 790","y":1928,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./160/790/","by":{"1":"28","2":"7, 8"}},{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"by":{"1":"37"},"q":[{"src":"brief","b":1,"text":"only applies if, after considering text, structure, history, and purpose, there remains a ‘grievous ambiguity or uncertainty in the statute,’","cite":"560 U.S. 474, 488"}]},{"t":"case","label":"Bateman Eichler, Hill Richards, Inc. v. Berner","cite":"472 U.S. 299","y":1985,"id":"1984/84-679","sc":1,"by":{"1":"26"}},{"t":"case","label":"Bettman v. United States","cite":"224 F. 819","y":1915,"url":"https://www.courtlistener.com/c/F./224/819/","by":{"1":"17"}},{"t":"case","label":"Chadbourne & Parke LLP v. Troice","cite":"134 S. Ct. 1058","y":2014,"id":"2013/12-79","sc":1,"by":{"1":"30","2":"14, 15"}},{"t":"case","label":"Charles Hughes & Co. v. SEC","cite":"139 F.2d 434","y":1943,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/139/434/","by":{"1":"29"},"q":[{"src":"argument","who":"Mr. Heim","text":"Lorenzo out of that subsection (b) realm and into (a) and (c) and even into 17(a)(1), there has to be some inherently deceptive conduct, such as creating a phony purchase order or a phony contract with Charles Vista to raise capital."}]},{"t":"case","label":"Cheney v. Powell","cite":"15 S.E. 750","y":1892,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./15/750/","by":{"1":"28","2":"8"}},{"t":"case","label":"DePierre v. United States","cite":"564 U.S. 70","y":2011,"id":"2010/09-1533","sc":1,"by":{"1":"37"}},{"t":"case","label":"Dura Pharms., Inc. v. Broudo","cite":"544 U.S. 336","y":2005,"id":"2004/03-932","sc":1,"by":{"1":"38"}},{"t":"case","label":"Durland v. United States","cite":"161 U.S. 306","y":1896,"id":"scdb/1895-139","sc":1,"by":{"1":"17","2":"15"},"q":[{"src":"brief","b":1,"text":"representations as to the past or present, or suggestions and promises as to the future.","cite":"161 U.S. 306, 313"}]},{"t":"case","label":"Exxon Co., U. S. A. v. Sofec, Inc.","cite":"517 U.S. 830","y":1996,"id":"1995/95-129","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"a court for correction of errors in fact finding.","cite":"517 U.S. 830, 841"}]},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"134 S. Ct. 2398","y":2014,"id":"2013/13-317","sc":1,"by":{"1":"38"},"q":[{"src":"brief","b":1,"text":"limits on damages and attorney’s fees, a ‘safe harbor’ for certain kinds of statements, restrictions on the selection of lead plaintiffs in securities class actions, sanctions for frivolous litigation, and stays of discovery pending motions to dismiss.","cite":"134 S. Ct. 2398, 2413"}]},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"differences in language * * * convey differences in meaning.","cite":"137 S. Ct. 1718, 1723"}]},{"t":"case","label":"Herman & MacLean v. Huddleston","cite":"459 U.S. 375","y":1983,"id":"1982/81-680","sc":1,"by":{"1":"26, 35"},"q":[{"src":"brief","b":1,"text":"an important purpose of the federal securities statutes was to rectify perceived deficiencies in the available common-law protections by establishing higher standards of conduct in the securities industry.","cite":"459 U.S. 375, 389"},{"src":"brief","b":1,"text":"‘prohibit some of the same conduct.’","cite":"459 U.S. at 383"},{"src":"argument","who":"Mr. Michel","text":"Another good example is the Herman and MacLean case that we cite in our brief. There, petitioner was -- the defendant was found liable under Rule 10b-5 for misstatements or omissions in a registration statement, even though Section 11 of the Securities Act applies expressly to misstatements in registration statements."}]},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"by":{"1":"37"},"q":[{"src":"brief","b":1,"text":"the equipoise of competing reasons cannot otherwise be resolved,","cite":"529 U.S. 694, 713 n.13"}]},{"t":"case","label":"Kardon v. National Gypsum Co.","cite":"73 F. Supp. 798","y":1947,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./73/798/","by":{"1":"29"}},{"t":"case","label":"Ki Se Lee v. Ashcroft","cite":"368 F.3d 218","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/368/218/","by":{"1":"36"}},{"t":"case","label":"MBIA Ins. Corp. v. Royal Indem. Co.","cite":"426 F.3d 204","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/426/204/","by":{"1":"27","2":"7"},"q":[{"src":"brief","b":1,"text":"is well known that the federal securities laws provide broader fraud protection than the common law, having been enacted in response to the common law’s perceived failure at stamping out fraud in the securities markets.","cite":"426 F.3d 204, 218"}]},{"t":"case","label":"Morrison v. National Austl. Bank Ltd.","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"by":{"1":"15"}},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"by":{"1":"37"}},{"t":"case","label":"Rubin v. United States","cite":"449 U.S. 424","y":1981,"id":"1980/79-1013","sc":1,"by":{"1":"15"},"q":[{"src":"brief","b":1,"text":"the terms of a statute [are] unambiguous, judicial inquiry is complete.","cite":"449 U.S. 424, 430"}]},{"t":"case","label":"SEC v. Capital Gains Research Bureau, Inc.","cite":"375 U.S. 180","y":1963,"id":"1963/42","sc":1,"by":{"1":"2, 35"},"q":[{"src":"brief","b":1,"text":"the first experiment in federal regulation of the securities industry,","cite":"375 U.S. 180, 198"},{"src":"brief","b":1,"text":"[t]he Securities Act of 1933 was the first experiment in federal regulation of the securities industry.","cite":"375 U.S. 180, 197-199"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"first experiment in federal regulation of the securities industry.","cite":"375 U. S. 180, 198"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"to substitute a philosophy of full disclosure for the philosophy of caveat emptor and thus to achieve a high standard of business ethics in the securities industry.","cite":"375 U. S., at 186"}]},{"t":"case","label":"SEC v. National Sec., Inc.","cite":"393 U.S. 453","y":1969,"id":"1968/41","sc":1,"by":{"1":"16","2":"14"},"q":[{"src":"brief","b":1,"text":"the type of fraudulent behavior which was meant to be forbidden by the statute and the rule.","cite":"393 U.S. 453, 467"}]},{"t":"case","label":"SEC v. W. J. Howey Co.","cite":"328 U.S. 293","y":1946,"id":"scdb/1945-134","sc":1,"by":{"1":"2"},"q":[{"src":"brief","b":1,"text":"embodies a flexible rather than a static principle, one that is capable of adaptation to meet the countless and variable schemes devised by those who seek the use of the money of others on the promise of profits.","cite":"328 U.S. 293, 299"}]},{"t":"case","label":"SEC v. Zandford","cite":"535 U.S. 813","y":2002,"id":"2001/01-147","sc":1,"by":{"1":"3"},"q":[{"src":"brief","b":1,"text":"achieve a high standard of business ethics in the securities industry,","cite":"535 U.S. 813, 819"}]},{"t":"case","label":"Speed v. Transamerica Corp.","cite":"99 F. Supp. 808","y":1951,"court":"D. Del.","url":"https://www.courtlistener.com/c/F.%20Supp./99/808/","by":{"1":"29"}},{"t":"case","label":"Superintendent of Ins. of N.Y. v. Bankers Life & Cas. Co.","cite":"404 U.S. 6","y":1971,"id":"1971/70-60","sc":1,"by":{"1":"16, 18","2":"14"}},{"t":"case","label":"United States v. Cronic","cite":"900 F.2d 1511","y":1990,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/900/1511/","by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"Although largely overlapping, a scheme to defraud, and a scheme to obtain money by means of false or fraudulent pretenses, representations, or promises, are separate offenses.","cite":"900 F.2d 1511, 1513"}]},{"t":"case","label":"United States v. Maze","cite":"414 U.S. 395","y":1974,"id":"1973/72-1168","sc":1,"by":{"1":"17","2":"15, 16"}},{"t":"case","label":"United States v. Naftalin","cite":"441 U.S. 768","y":1979,"id":"1978/78-561","sc":1,"by":{"1":"18, 26, 35"},"q":[{"src":"brief","b":1,"text":"meant to cover additional kinds of illegalities.","cite":"441 U.S. at 774"},{"src":"brief","b":1,"text":"is meant to cover additional kinds of illegalities—not to narrow the reach of the prior sections.","cite":"441 U.S. at 774"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"meant to cover additional kinds of illegalities—not to narrow the reach of the prior sections.","cite":"441 U. S. 768, 774"},{"src":"argument","who":"Mr. Heim","text":"And this Court, in U.S. versus Naftalin, was addressing Section 17(a) and its different subsections, and it said that each subsection prohibits a different type of conduct."}]},{"t":"case","label":"United States v. Swanson","cite":"360 F.3d 1155","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/360/1155/","by":{"1":"35"}},{"t":"case","label":"United States v. Yeaman","cite":"194 F.3d 442","y":1999,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/194/442/","by":{"1":"35"}},{"t":"case","label":"Wharf (Holdings) Ltd. v. United Int’l Holdings, Inc.","cite":"532 U.S. 588","y":2001,"id":"2000/00-347","sc":1,"by":{"1":"19, 20"}},{"t":"case","label":"Wilson v. United States","cite":"190 F. 427","y":1911,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F./190/427/","by":{"1":"17"}},{"t":"case","label":"Zuckerman v. Cochran","cite":"158 So. 324","y":1934,"court":"Ala.","url":"https://www.courtlistener.com/c/So./158/324/","by":{"1":"27","2":"7, 8"}},{"t":"law","label":"Pub. L. No. 104-67","url":"https://www.govinfo.gov/link/plaw/104/public/67","by":{"1":"14","2":"21, 22"}},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 78u-4","url":"https://www.law.cornell.edu/uscode/text/15/78u-4","subs":["(b)(1)"],"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"if an allegation regarding the statement or omission is made on information and belief, the complaint shall state with particularity all facts on which that belief is formed.","cite":"15 U.S.C. 78u-4(b)(1)"}]},{"t":"usc","label":"15 U.S.C. § 78y","url":"https://www.law.cornell.edu/uscode/text/15/78y","subs":["(a)(4)"],"stext":{"head":"§78y. Court review of orders and rules","paras":[[0,"(a) Final Commission orders; persons aggrieved; petition; record; findings; affirmance, modification, enforcement, or setting aside of orders; remand to adduce additional evidence"],[0,"(1) A person aggrieved by a final order of the Commission entered pursuant to this chapter may obtain review of the order in the United States Court of Appeals for the circuit in which he resides or has his principal place of business, or for the District of Columbia Circuit, by filing in such court, within sixty days after the entry of the order, a written petition requesting that the order be modified or set aside in whole or in part."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated by the Commission for that purpose. Thereupon the Commission shall file in the court the record on which the order complained of is entered, as provided in section 2112 of title 28 and the Federal Rules of Appellate Procedure."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the record, to affirm or modify and enforce or to set aside the order in whole or in part."],[0,"(4) The findings of the Commission as to the facts, if supported by substantial evidence, are conclusive."],[0,"(5) If either party applies to the court for leave to adduce additional evidence and shows to the satisfaction of the court that the additional evidence is material and that there was reasonable ground for failure to adduce it before the Commission, the court may remand the case to the Commission for further proceedings, in whatever manner and on whatever conditions the court considers appropriate. If the case is remanded to the Commission, it shall file in the court a supplemental record containing any new evidence, any further or modified findings, and any new order."],[0,"(b) Commission rules; persons adversely affected; petition; record; affirmance, enforcement, or setting aside of rules; findings; transfer of proceedings"],[0,"(1) A person adversely affected by a rule of the Commission promulgated pursuant to section 78f, 78i(h)(2), 78k, 78k–1, 78o(c)(5) or (6), 78o–3, 78q, 78q–1, or 78s of this title may obtain review of this rule in the United States Court of Appeals for the circuit in which he resides or has his principal place of business or for the District of Columbia Circuit, by filing in such court, within sixty days after the promulgation of the rule, a written petition requesting that the rule be set aside."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated for that purpose. Thereupon, the Commission shall file in the court the rule under review and any documents referred to therein, the Commission's notice of proposed rulemaking and any documents referred to therein, all written submissions and the transcript of any oral presentations in the rulemaking, factual information not included in the foregoing that was considered by the Commission in the promulgation of the rule or proffered by the Commission as pertinent to the rule, the report of any advisory committee received or considered by the Commission in the rulemaking, and any other materials prescribed by the court."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the materials set forth in paragraph (2) of this subsection, to affirm and enforce or to set aside the rule."],[0,"(4) The findings of the Commission as to the facts identified by the Commission as the basis, in whole or in part, of the rule, if supported by substantial evidence, are conclusive. The court shall affirm and enforce the rule unless the Commission's action in promulgating the rule is found to be arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law; contrary to constitutional right, power, privilege, or immunity; in excess of statutory jurisdiction, authority, or limitations, or short of statutory right; or without observance of procedure required by law."],[0,"(5) If proceedings have been instituted under this subsection in two or more courts of appeals with respect to the same rule, the Commission shall file the materials set forth in paragraph (2) of this subsection in that court in which a proceeding was first instituted. The other courts shall thereupon transfer all such proceedings to the court in which the materials have been filed. For the convenience of the parties in the interest of justice that court may thereafter transfer all the proceedings to any other court of appeals."],[0,"(c) Objections not urged before Commission; stay of orders and rules; transfer of enforcement or review proceedings"],[0,"(1) No objection to an order or rule of the Commission, for which review is sought under this section, may be considered by the court unless it was urged before the Commission or there was reasonable ground for failure to do so."],[0,"(2) The filing of a petition under this section does not operate as a stay of the Commission's order or rule. Until the court's jurisdiction becomes exclusive, the Commission may stay its order or rule pending judicial review if it finds that justice so requires. After the filing of a petition under this section, the court, on whatever conditions may be required and to the extent necessary to prevent irreparable injury, may issue all necessary and appropriate process to stay the order or rule or to preserve status or rights pending its review; but (notwithstanding section 705 of title 5) no such process may be issued by the court before the filing of the record or the materials set forth in subsection (b)(2) of this section unless: (A) the Commission has denied a stay or failed to grant requested relief, (B) a reasonable period has expired since the filing of an application for a stay without a decision by the Commission, or (C) there was reasonable ground for failure to apply to the Commission."],[0,"(3) When the same order or rule is the subject of one or more petitions for review filed under this section and an action for enforcement filed in a district court of the United States under section 78u(d) or (e) of this title, that court in which the petition or the action is first filed has jurisdiction with respect to the order or rule to the exclusion of any other court, and thereupon all such proceedings shall be transferred to that court; but, for the convenience of the parties in the interest of justice, that court may thereafter transfer all the proceedings to any other court of appeals or district court of the United States, whether or not a petition for review or an action for enforcement was originally filed in the transferee court. The scope of review by a district court under section 78u(d) or (e) of this title is in all cases the same as by a court of appeals under this section."],[0,"(d) Other appropriate regulatory agencies"],[0,"(1) For purposes of the preceding subsections of this section, the term \"Commission\" includes the agencies enumerated in section 78c(a)(34) of this title insofar as such agencies are acting pursuant to this chapter and the Secretary of the Treasury insofar as he is acting pursuant to section 78o–5 of this title."],[0,"(2) For purposes of subsection (a)(4) of this section and section 706 of title 5, an order of the Commission pursuant to section 78s(a) of this title denying registration to a clearing agency for which the Commission is not the appropriate regulatory agency or pursuant to section 78s(b) of this title disapproving a proposed rule change by such a clearing agency shall be deemed to be an order of the appropriate regulatory agency for such clearing agency insofar as such order was entered by reason of a determination by such appropriate regulatory agency pursuant to section 78s(a)(2)(C) or 78s(b)(4)(C) of this title that such registration or proposed rule change would be inconsistent with the safeguarding of securities or funds."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78y?type=usc&year=mostrecent&link-type=html"},"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"if supported by substantial evidence, are conclusive.","cite":"15 U.S.C. 78y(a)(4)"}]},{"t":"usc","label":"26 U.S.C. § 7201","url":"https://www.law.cornell.edu/uscode/text/26/7201","by":{"1":"36"}},{"t":"reg","label":"7 Fed. Reg. 3804","url":"https://www.govinfo.gov/link/fr/7/3804","by":{"1":"4"}},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"by":{"2":"19"}},{"t":"case","label":"Dinsmore v. Squadron, Ellenoff, Plesent, Sheinfeld & Sorkin","cite":"135 F.3d 837","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/135/837/","by":{"2":"8"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Dabit","cite":"547 U.S. 71","y":2006,"id":"2005/04-1371","sc":1,"by":{"2":"22"}},{"t":"case","label":"Nat’l Ass’n Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"by":{"2":"5, 6"},"q":[{"src":"brief","b":2,"text":"against reading a text in a way that makes part of it redundant","cite":"551 U.S. 644, 669"}]},{"t":"case","label":"Pepper v. Litton","cite":"308 U.S. 295","y":1939,"id":"scdb/1939-033","sc":1,"by":{"2":"8"}},{"t":"case","label":"SEC v. Quan","cite":"817 F.3d 583","y":2016,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/817/583/","by":{"2":"15"},"q":[{"src":"brief","b":2,"text":"conduct beyond just misrepresentations or omissions.","cite":"817 F.3d 583, 589"}]},{"t":"case","label":"Stewart v. Wyoming Cattle-Ranche Co.","cite":"128 U.S. 383","y":1888,"id":"scdb/1888-038","sc":1,"by":{"2":"9"}},{"t":"case","label":"Strong v. Repide","cite":"213 U.S. 419","y":1909,"id":"scdb/1908-138","sc":1,"by":{"2":"8"}},{"t":"usc","label":"15 U.S.C. § 77o","url":"https://www.law.cornell.edu/uscode/text/15/77o","subs":["(b)"],"by":{"2":"20"}},{"t":"usc","label":"15 U.S.C. § 78bb","url":"https://www.law.cornell.edu/uscode/text/15/78bb","subs":["(f)(1)(A)"],"stext":{"head":"§78bb. Effect on existing law","paras":[[0,"(a) Limitation on judgments"],[0,"(1) In general"],[1,"No person permitted to maintain a suit for damages under the provisions of this chapter shall recover, through satisfaction of judgment in 1 or more actions, a total amount in excess of the actual damages to that person on account of the act complained of. Except as otherwise specifically provided in this chapter, nothing in this chapter shall affect the jurisdiction of the securities commission (or any agency or officer performing like functions) of any State over any security or any person insofar as it does not conflict with the provisions of this chapter or the rules and regulations under this chapter."],[0,"(2) Rule of construction"],[1,"Except as provided in subsection (f), the rights and remedies provided by this chapter shall be in addition to any and all other rights and remedies that may exist at law or in equity."],[0,"(3) State bucket shop laws"],[1,"No State law which prohibits or regulates the making or promoting of wagering or gaming contracts, or the operation of \"bucket shops\" or other similar or related activities, shall invalidate—"],[2,"(A) any put, call, straddle, option, privilege, or other security subject to this chapter (except any security that has a pari-mutuel payout or otherwise is determined by the Commission, acting by rule, regulation, or order, to be appropriately subject to such laws), or apply to any activity which is incidental or related to the offer, purchase, sale, exercise, settlement, or closeout of any such security;"],[2,"(B) any security-based swap between eligible contract participants; or"],[2,"(C) any security-based swap effected on a national securities exchange registered pursuant to section 78f(b) of this title."],[0,"(4) Other State provisions"],[1,"No provision of State law regarding the offer, sale, or distribution of securities shall apply to any transaction in a security-based swap or a security futures product, except that this paragraph may not be construed as limiting any State antifraud law of general applicability. A security-based swap may not be regulated as an insurance contract under any provision of State law."],[0,"(b) Modification of disciplinary procedures"],[0,"Nothing in this chapter shall be construed to modify existing law with regard to the binding effect (1) on any member of or participant in any self-regulatory organization of any action taken by the authorities of such organization to settle disputes between its members or participants, (2) on any municipal securities dealer or municipal securities broker of any action taken pursuant to a procedure established by the Municipal Securities Rulemaking Board to settle disputes between municipal securities dealers and municipal securities brokers, or (3) of any action described in paragraph (1) or (2) on any person who has agreed to be bound thereby."],[0,"(c) Continuing validity of disciplinary sanctions"],[0,"The stay, setting aside, or modification pursuant to section 78s(e) of this title of any disciplinary sanction imposed by a self-regulatory organization on a member thereof, person associated with a member, or participant therein, shall not affect the validity or force of any action taken as a result of such sanction by the self-regulatory organization prior to such stay, setting aside, or modification: Provided, That such action is not inconsistent with the provisions of this chapter or the rules or regulations thereunder. The rights of any person acting in good faith which arise out of any such action shall not be affected in any way by such stay, setting aside, or modification."],[0,"(d) Physical location of facilities of registered clearing agencies or registered transfer agents not to subject changes in beneficial or record ownership of securities to State or local taxes"],[0,"No State or political subdivision thereof shall impose any tax on any change in beneficial or record ownership of securities effected through the facilities of a registered clearing agency or registered transfer agent or any nominee thereof or custodian therefor or upon the delivery or transfer of securities to or through or receipt from such agency or agent or any nominee thereof or custodian therefor, unless such change in beneficial or record ownership or such transfer or delivery or receipt would otherwise be taxable by such State or political subdivision if the facilities of such registered clearing agency, registered transfer agent, or any nominee thereof or custodian therefor were not physically located in the taxing State or political subdivision. No State or political subdivision thereof shall impose any tax on securities which are deposited in or retained by a registered clearing agency, registered transfer agent, or any nominee thereof or custodian therefor, unless such securities would otherwise be taxable by such State or political subdivision if the facilities of such registered clearing agency, registered transfer agent, or any nominee thereof or custodian therefor were not physically located in the taxing State or political subdivision."],[0,"(e) Exchange, broker, and dealer commissions; brokerage and research services"],[0,"(1) No person using the mails, or any means or instrumentality of interstate commerce, in the exercise of investment discretion with respect to an account shall be deemed to have acted unlawfully or to have breached a fiduciary duty under State or Federal law unless expressly provided to the contrary by a law enacted by the Congress or any State subsequent to June 4, 1975, solely by reason of his having caused the account to pay a member of an exchange, broker, or dealer an amount of commission for effecting a securities transaction in excess of the amount of commission another member of an exchange, broker, or dealer would have charged for effecting that transaction, if such person determined in good faith that such amount of commission was reasonable in relation to the value of the brokerage and research services provided by such member, broker, or dealer, viewed in terms of either that particular transaction or his overall responsibilities with respect to the accounts as to which he exercises investment discretion. This subsection is exclusive and plenary insofar as conduct is covered by the foregoing, unless otherwise expressly provided by contract: Provided, however, That nothing in this subsection shall be construed to impair or limit the power of the Commission under any other provision of this chapter or otherwise."],[0,"(2) A person exercising investment discretion with respect to an account shall make such disclosure of his policies and practices with respect to commissions that will be paid for effecting securities transactions, at such times and in such manner, as the appropriate regulatory agency, by rule, may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[0,"(3) For purposes of this subsection a person provides brokerage and research services insofar as he—"],[1,"(A) furnishes advice, either directly or through publications or writings, as to the value of securities, the advisability of investing in, purchasing, or selling securities, and the availability of securities or purchasers or sellers of securities;"],[1,"(B) furnishes analyses and reports concerning issuers, industries, securities, economic factors and trends, portfolio strategy, and the performance of accounts; or"],[1,"(C) effects securities transactions and performs functions incidental thereto (such as clearance, settlement, and custody) or required in connection therewith by rules of the Commission or a self-regulatory organization of which such person is a member or person associated with a member or in which such person is a participant."],[0,"(4) The provisions of this subsection shall not apply with regard to securities that are security futures products."],[0,"(f) Limitations on remedies"],[0,"(1) Class action limitations"],[1,"No covered class action based upon the statutory or common law of any State or subdivision thereof may be maintained in any State or Federal court by any private party alleging—"],[2,"(A) a misrepresentation or omission of a material fact in connection with the purchase or sale of a covered security; or"],[2,"(B) that the defendant used or employed any manipulative or deceptive device or contrivance in connection with the purchase or sale of a covered security."],[0,"(2) Removal of covered class actions"],[1,"Any covered class action brought in any State court involving a covered security, as set forth in paragraph (1), shall be removable to the Federal district court for the district in which the action is pending, and shall be subject to paragraph (1)."],[0,"(3) Preservation of certain actions"],[0,"(A) Actions under State law of State of incorporation"],[0,"(i) Actions preserved"],[3,"Notwithstanding paragraph (1) or (2), a covered class action described in clause (ii) of this subparagraph that is based upon the statutory or common law of the State in which the issuer is incorporated (in the case of a corporation) or organized (in the case of any other entity) may be maintained in a State or Federal court by a private party."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78bb?type=usc&year=mostrecent&link-type=html"},"by":{"2":"15"},"q":[{"src":"brief","b":2,"text":"(A) a misrepresentation or omission of a material fact in connection with the purchase or sale of a covered security; or (B) that the defendant used or employed any manipulative or deceptive device or contrivance in connection with the purchase or sale of a covered security.","cite":"15 U.S.C. § 78bb(f)(1)(A)"}]},{"t":"usc","label":"15 U.S.C. § 78i","url":"https://www.law.cornell.edu/uscode/text/15/78i","subs":["(a)(5)"],"by":{"2":"12, 13"}}]};